25		<style>
26			:root {
27				color-scheme: light dark;
28				--text: #1a1a1a;
29				--text-secondary: #555;
30				--background: #fff;
31				--accent: #0052a3;
32				--border: #e0e0e0;
33			}
34			@media (prefers-color-scheme: dark) {
35				:root {
36					--text: #e0e0e0;
37					--text-secondary: #a0a0a0;
38					--background: #121212;
39					--accent: #5fa3ff;
40					--border: #333;
41				}
42			}
43			*,
44			*::before,
45			*::after {
46				box-sizing: border-box;
47			}
48			html {
49				-webkit-text-size-adjust: 100%;
50				text-size-adjust: 100%;
51			}
52			@media (prefers-reduced-motion: no-preference) {
53				html {
54					scroll-behavior: smooth;
55				}
56				a {
57					transition: text-decoration-thickness 0.15s ease;
58				}
59				.skip-link {
60					transition: transform 0.15s ease;
61				}
62			}
63			body {
64				display: grid;
65				grid-template-rows: auto 1fr auto;
66				min-height: 100vh;
67				min-height: 100dvh;
68				font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
69				font-size: 1rem;
70				line-height: 1.6;
71				max-width: 70ch;
72				margin: 0 auto;
73				padding: max(1.25rem, env(safe-area-inset-top)) max(1.25rem, env(safe-area-inset-right)) max(1.25rem, env(safe-area-inset-bottom)) max(1.25rem, env(safe-area-inset-left));
74				color: var(--text);
75				background: var(--background);
76			}
77			h1 {
78				color: var(--accent);
79				font-size: clamp(1.75rem, 1.25rem + 3vw, 2.5rem);
80				font-weight: 700;
81				line-height: 1.1;
82				text-wrap: balance;
83				margin: 0 0 1.5rem 0;
84				letter-spacing: -0.02em;
85			}
86			p {
87				text-wrap: pretty;
88				margin: 1rem 0;
89			}
90			a {
91				color: var(--accent);
92				text-underline-offset: 0.2em;
93				text-decoration-thickness: 2px;
94				font-weight: 500;
95			}
96			a:hover, a:active {
97				text-decoration-thickness: 3px;
98			}
99			:focus-visible {
100				outline: 2px solid var(--accent);
101				outline-offset: 2px;
102			}
103			.skip-link {
104				position: absolute;
105				left: 0;
106				top: 0;
107				transform: translateY(-100%);
108				background: var(--accent);
109				color: var(--background);
110				padding: 0.75rem 1.5rem;
111				z-index: 1000;
112				border-radius: 0 0 0.25rem 0;
113				font-weight: 600;
114				text-decoration: none;
115				display: inline-block;
116			}
117			.skip-link:focus {
118				transform: none;
119				outline: 3px solid var(--text);
120				outline-offset: -3px;
121			}
122			header {
123				padding-block: 1.5rem 0;
124			}
125			main {
126				padding: 1rem 0;
127			}
128			main:focus {
129				outline: none;
130			}
131			footer {
132				padding-block: 1.5rem;
133				margin-top: 3rem;
134				border-top: 1px solid var(--border);
135				font-size: 0.875rem;
136				color: var(--text-secondary);
137				text-align: center;
138			}
139			footer p {
140				margin: 0.5rem 0;
141			}
142			@media print {
143				.skip-link {
144					display: none;
145				}
146				body {
147					display: block;
148					min-height: 0;
149					max-width: none;
150					padding: 0;
151				}
152				a {
153					color: inherit;
154					text-decoration: underline;
155				}
156			}
157		</style>
158	</head>
159	<body>
160		<a class="skip-link" href="#main">Skip to content</a>
161		<header>
162			<h1>Welcome</h1>
163		</header>
164		<main id="main" tabindex="-1">
165			<p>This is a well-structured, accessible HTML5 document.</p>
166			<p>
167				It uses semantic landmarks, a skip link for keyboard navigation,
168				and CSS that adapts to your light or dark mode preference.
169			</p>
170			<p>
171				Text and link colors meet WCAG AA contrast in both themes, type scales
172				with your browser's font size, and motion respects your system settings.
173			</p>
174		</main>
175		<footer>
176			<p>&copy; 2026. All rights reserved.</p>
177		</footer>
178	</body>
179	</html>
